root=Path(__file__).resolve().parents[2];p=root/'research/nine-sharing-sign16-coordinate-check';draft=root/'research/nine-sharing-sign16-coordinate-draft';sha=lambda q:hashlib.sha256(q.read_bytes()).hexdigest();run=p/'run.py';m=p/'source-manifest.json';assert sha(run)=='ecb0fea190f7c871bd67df2ad3f68a4a2ac0b3cf4627a8de73023d46fda111c0' and sha(m)=='d01628e58607ca9c583454c60df67f32e83a5c401121454e849f1586fd8e0edb';row,=json.loads(m.read_text())['rows'];name='Sign16Coordinate';src=p/'src/DiophantineConsistency'/(name+'.lean');s=src.read_text();assert sha(src)==sha(draft/(name+'.lean'))==row['source_sha256']=='f5a88a87008fee654c3d38f890bc01e6855213b046471126907ad93f8a08bd17' and row['module']=='DiophantineConsistency.'+name and re.findall(r'^import ([A-Za-z0-9_.]+)$',s,re.M)==row['imports']==['DiophantineConsistency.SharingSign16Squares','DiophantineConsistency.SharingSign17Squares','DiophantineConsistency.Sign16SharedValues'];assert not re.search(r'(?m)^\s*(axiom|opaque)\b|\b(sorry|admit)\b',s)
