checks=[('reviews/nine-sharing-sign16-staged-syntax-terminal-independent/check.py','5a71b6e4c81c3ac85590e5f702bcadb952889bd3cf2a7b21a49baa74d8ca1758'),('reviews/nine-sharing-sign17-staged-syntax-terminal-independent/check.py','c5f9c82d8c8d8ada75c848532301f1a199090aefb25c1f4aa622651b2ed8eedf'),('reviews/nine-sharing-sign16-shared-values-terminal-independent/check.py','8ea33335c88381edc5056b39b20240fce0128a2159aae2834e21efeae703b552'),('reviews/nine-sharing-sign16-v-lift-retry01-terminal-independent/check.py','0d113d5ee9f3e53e70c39b7334fb03d21af13a0560e681bd3e93104233d1fe06')]
for path,pin in checks:
 check=root/path;assert sha(check)==pin;subprocess.run([sys.executable,'-I','-S','-B',str(check)],capture_output=True,check=True,timeout=120)
z=subprocess.run([sys.executable,'-I','-S','-B',str(survey)],capture_output=True,text=True,check=True,timeout=180);data=json.loads(z.stdout);assert data['status']=='PASS' and len(data['extra'])==17 and len(data['producers'])==2
